import { createReadStream } from 'node:fs';

/** Make a POSIX ustar header; all file paths in the archive are generated by this service. */
export function tarHeader(name:string,size:number,mtime=Date.now()) {
  const buf=Buffer.alloc(512,0);
  const write=(value:string,offset:number,length:number)=>buf.write(value.slice(0,length),offset,length,'utf8');
  const oct=(value:number,offset:number,length:number)=>write(Math.floor(value).toString(8).padStart(length-1,'0')+'\0',offset,length);
  if(Buffer.byteLength(name)>100 || size<0 || !Number.isSafeInteger(size)) throw new Error('Invalid TAR entry');
  write(name,0,100);oct(0o600,100,8);oct(0,108,8);oct(0,116,8);oct(size,124,12);oct(Math.floor(mtime/1000),136,12);
  buf.fill(32,148,156);buf[156]=48;write('ustar\0',257,6);write('00',263,2);
  const checksum=buf.reduce((sum,b)=>sum+b,0);
  oct(checksum,148,8);
  return buf;
}
export async function* archiveEntries(entries:Array<{name:string;file?:string;content?:Buffer;size:number}>) {
  for(const entry of entries){
    yield tarHeader(entry.name,entry.size);
    if(entry.content) yield entry.content;
    else if(entry.file) for await(const chunk of createReadStream(entry.file)) yield chunk as Buffer;
    if(entry.size%512)yield Buffer.alloc(512-(entry.size%512));
  }
  yield Buffer.alloc(1024);
}
